import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.QP0FkqbW.js";const u=JSON.parse('{"title":"Installation & Setup Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),o={name:"guide/installation.md"};function l(r,e,s,c,d,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="installation-setup-guide" tabindex="-1">Installation &amp; Setup Guide <a class="header-anchor" href="#installation-setup-guide" aria-label="Permalink to &quot;Installation &amp; Setup Guide&quot;">​</a></h1><p>Quick start guide for installing and configuring KUKA KRL Professional.</p><h2 id="_1-install-via-vs-code-marketplace" tabindex="-1">1. Install via VS Code Marketplace <a class="header-anchor" href="#_1-install-via-vs-code-marketplace" aria-label="Permalink to &quot;1. Install via VS Code Marketplace&quot;">​</a></h2><ol><li>Open VS Code.</li><li>Go to the Extensions view (<code>Ctrl + Shift + X</code>).</li><li>Search for <code>KUKA KRL Professional</code>.</li><li>Click <strong>Install</strong>.</li></ol><h2 id="_2-install-from-vsix-offline-installation" tabindex="-1">2. Install from VSIX (Offline Installation) <a class="header-anchor" href="#_2-install-from-vsix-offline-installation" aria-label="Permalink to &quot;2. Install from VSIX (Offline Installation)&quot;">​</a></h2><ol><li>Download the <code>kuka-krl-extension-1.7.3.vsix</code> file.</li><li>In VS Code, click the <code>...</code> menu in the top-right corner of the Extensions panel.</li><li>Select <strong>Install from VSIX...</strong> and choose the <code>.vsix</code> file.</li></ol><h2 id="_3-selecting-a-kuka-theme" tabindex="-1">3. Selecting a KUKA Theme <a class="header-anchor" href="#_3-selecting-a-kuka-theme" aria-label="Permalink to &quot;3. Selecting a KUKA Theme&quot;">​</a></h2><ol><li>Press <code>Ctrl + K</code>, then <code>Ctrl + T</code>.</li><li>Select one of the 6 signature themes: <strong>Industrial Dark</strong>, <strong>WorkVisual Dark</strong>, <strong>WorkVisual Light</strong>, <strong>Midnight OLED</strong>, <strong>Blueprint</strong>, <strong>Industrial Light</strong>.</li></ol><h2 id="_4-activating-pro-license" tabindex="-1">4. Activating Pro License <a class="header-anchor" href="#_4-activating-pro-license" aria-label="Permalink to &quot;4. Activating Pro License&quot;">​</a></h2><ol><li>Open the <strong>KUKA Control Center</strong> by clicking the KUKA icon in the Activity Bar or running <code>KRL: Open Control Center</code>.</li><li>Click <strong>Enter License Key</strong>.</li><li>Paste your Lemon Squeezy key and click <strong>Activate</strong>.</li></ol><h2 id="_5-telegram-engineering-support" tabindex="-1">5. Telegram Engineering Support <a class="header-anchor" href="#_5-telegram-engineering-support" aria-label="Permalink to &quot;5. Telegram Engineering Support&quot;">​</a></h2><p>For technical support, connect with us using the embedded support panel or via our Telegram bot <strong><code>@kukakrlbot</code></strong>.</p>',12)])])}const p=t(o,[["render",l]]);export{u as __pageData,p as default};
